package main
import("context";"encoding/json";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();q:=`WITH graded AS (SELECT h.recording_id,h.job_id,(h.window_start_at AT TIME ZONE r.cron_timezone)::date d,CASE WHEN h.metric_version IS NULL OR h.metric_version<>2 OR h.gap_over_30s_count IS NULL OR h.gap_over_5m_count IS NULL THEN 'U' WHEN h.overlap_count=0 AND h.coverage_pct>=99 AND h.largest_gap_seconds<=120 THEN 'A' WHEN h.overlap_count=0 AND h.coverage_pct>=95 AND h.largest_gap_seconds<=900 AND h.gap_over_5m_count<=1 AND h.gap_over_30s_count<=6 THEN 'B' WHEN h.overlap_count=0 AND h.coverage_pct>=90 AND h.largest_gap_seconds<=1800 AND h.gap_over_5m_count<=2 THEN 'C' WHEN h.clip_count=0 OR h.coverage_pct=0 THEN 'F' WHEN h.coverage_pct<80 THEN 'E' ELSE 'D' END g FROM recording_window_health h JOIN recordings r ON r.id=h.recording_id WHERE r.account_id=47 AND r.mode='continuous'), w AS (SELECT *,lead(d,13) OVER(PARTITION BY recording_id ORDER BY d,job_id) ed,count(*) OVER(PARTITION BY recording_id ORDER BY d,job_id ROWS BETWEEN CURRENT ROW AND 13 FOLLOWING) n,count(*) FILTER(WHERE g IN('F','U')) OVER(PARTITION BY recording_id ORDER BY d,job_id ROWS BETWEEN CURRENT ROW AND 13 FOLLOWING) bad,count(*) FILTER(WHERE g='E') OVER(PARTITION BY recording_id ORDER BY d,job_id ROWS BETWEEN CURRENT ROW AND 13 FOLLOWING) es FROM graded), qual AS (SELECT recording_id,bool_or(n=14 AND ed=d+13) fine,bool_or(n=14 AND ed=d+13 AND bad=0 AND es<=2) good,bool_or(n=14 AND ed=d+13 AND bad=0 AND es=0 AND NOT EXISTS(SELECT 1 FROM w x WHERE x.recording_id=w.recording_id AND x.d BETWEEN w.d AND w.d+13 AND x.g NOT IN('A','B','C'))) great FROM w GROUP BY recording_id) SELECT jsonb_build_object('fine',count(*) FILTER(WHERE fine),'good',count(*) FILTER(WHERE good),'great',count(*) FILTER(WHERE great),'fine_ids',coalesce(array_agg(recording_id) FILTER(WHERE fine),'{}'),'good_ids',coalesce(array_agg(recording_id) FILTER(WHERE good),'{}'),'great_ids',coalesce(array_agg(recording_id) FILTER(WHERE great),'{}')) FROM qual`;var b []byte;if e=p.QueryRow(c,q).Scan(&b);e!=nil{panic(e)};var v any;_ = json.Unmarshal(b,&v);out,_:=json.Marshal(v);fmt.Println(string(out))}
